                    const playerName = (nickInput && nickInput.value) ? nickInput.value : (e?.user?.nickname || "Player");

                    const gauges = typeof getGaugesState === "function" ? getGaugesState(e) : null;
                    let rawFood = gauges?.hunger !== undefined ? gauges.hunger : 100;
                    let rawWater = gauges?.thrist !== undefined ? gauges.thrist : 100;
                    
                    const foodPct = Math.round(rawFood);
