                    const waterBedMin = formatMinutes(waterSecInBed);

                    const foodStr = foodItemsList.length > 0 ? foodItemsList.join(" ") : "none";
                    const waterStr = waterItemsList.length > 0 ? waterItemsList.join(" ") : "none";

