      draw(ctx) {
        if (!this.enabled || this.main.hidden || !ctx || !this.main.is_game_running()) return;

        const units = this.main.world?.units?.[A] ?? [];
        const players = this.main.world?.players ?? [];
        const cam = this.main.user?.cam;
        if (!cam) return;

        ctx.save();
        ctx.font = "18px 'Baloo Paaji', sans-serif";
        ctx.textAlign = "center";
        ctx.lineWidth = 4;
        ctx.strokeStyle = "#000000";
        ctx.fillStyle = "#ffffff";

        for (let i = 0; i < units.length; i++) {
          const u = units[i];
          if (!u) continue;

          const keys = Object.keys(u);
          const clothe = typeof u.clothe === "number" ? u.clothe : u[keys[66]];
          const isGhost = typeof u.ghost === "boolean" ? u.ghost : Boolean(u[keys[67]]);
          const isHood = clothe === Items.HOOD || clothe === Items.WINTER_HOOD;

          if (!isHood && !isGhost) continue;

          const pid = u.pid ?? u[keys[1]];
          // Берем данные игрока из индекса 14 дампа fix.js или из world.players[pid]
          const pData = u.player_data || u[keys[14]] || players[pid];
          if (!pData || typeof pData !== "object") continue;

          const nickname = Object.values(pData)[0];
          const level = pData.level;

          if (typeof nickname === "string" && nickname.trim().length > 0) {
            const displayText = level !== undefined ? `${nickname.trim()} (${level})` : nickname.trim();
            const sx = cam.x + u.x;
            const sy = cam.y + u.y - 48;

            ctx.strokeText(displayText, sx, sy);
            ctx.fillText(displayText, sx, sy);
          }
        }

        ctx.restore();
      }
