        const fill = document.createElement("div");
        fill.className = "acb-fill";
        const thumb = document.createElement("div");
        thumb.className = "acb-thumb";
        const range = document.createElement("input");
        range.type = "range"; range.className = "acb-range"; range.min = 10; range.step = 10; range.tabIndex = -1;
        track.append(fill, thumb, range);

        const num = document.createElement("input");
        num.type = "number"; num.className = "acb-num"; num.min = 10; num.step = 1;
        num.setAttribute("autocomplete", "off");

        bar.append(label, track, num);
        document.body.appendChild(bar);
        this._bar = bar; this._barLabel = label; this._barRange = range; this._barNum = num;
        this._barFillEl = fill; this._barThumb = thumb; this._barStyle = style;

